parameters.jsCode:
const rows = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const call = body.call ?? {};
  const customer = body.customer ?? call.customer ?? {};
  const callId = String(call.id ?? body.callId ?? body.call_id ?? '').trim();
  const endedReason = String(call.endedReason ?? body.endedReason ?? body.ended_reason ?? '').trim();
  const transcript = String(body.transcript ?? call.transcript ?? '').trim();
  const summary = String(body.summary ?? call.summary ?? body.analysis?.summary ?? '').trim();
  const callerPhoneFromPlatform = String(customer.number ?? body.callerPhone ?? body.from ?? '').trim();
  rows.push({ json: {
    callId,
    endedReason,
    transcript,
    summary,
    callerPhoneFromPlatform,
    receivedAt: new Date().toISOString()
  } });
}
return rows;

const FAILURE_ENDED_REASONS = ['no-answer','voicemail','customer-did-not-give-microphone-permission','customer-did-not-answer','busy','customer-busy','error','pipeline-error','assistant-error','call-start-error-neither-assistant-nor-server-set','silence-timed-out','exceeded-max-duration','dial-busy','dial-no-answer'];
const rows = [];
for (const item of $input.all()) {
  const data = item.json;
  const reason = String(data.endedReason || '').toLowerCase();
  const transcriptText = String(data.transcript || data.summary || '').trim();
  const hasWords = transcriptText.length > 0;
  const isFailureReason = FAILURE_ENDED_REASONS.indexOf(reason) !== -1;
  const hasUsableTranscript = hasWords && !isFailureReason;
  const reasons = [];
  if (!hasWords) { reasons.push('no transcript or summary text on the payload'); }
  if (isFailureReason) { reasons.push('endedReason is "' + (reason || 'unknown') + '", a known failure code'); }
  rows.push({ json: Object.assign({}, data, {
    hasUsableTranscript,
    unprocessableReason: reasons.join('; ')
  }) });
}
return rows;

