parameters.jsCode:
const settings = $('Handoff Settings').first().json;
const original = $('Normalise Call Payload').first().json;
const urgentKeywords = Array.isArray(settings.urgentKeywords) ? settings.urgentKeywords : [];
const rows = [];
for (const item of $input.all()) {
  const extracted = item.json.output ? item.json.output : item.json;
  const sentiment = String(extracted.sentiment || 'neutral').toLowerCase();
  const urgency = String(extracted.urgency || 'low').toLowerCase();
  const summary = String(extracted.summary || '').trim();
  const intent = String(extracted.intent || '').trim();
  const haystack = (summary + ' ' + intent).toLowerCase();
  const matchedKeywords = urgentKeywords.filter(function (word) {
    return haystack.indexOf(String(word).toLowerCase()) !== -1;
  });
  const reasons = [];
  if (urgency === 'high') { reasons.push('model marked urgency high'); }
  if (sentiment === 'negative') { reasons.push('model marked sentiment negative'); }
  if (matchedKeywords.length > 0) { reasons.push('summary/intent matched keyword(s): ' + matchedKeywords.join(', ')); }
  const urgent = reasons.length > 0;
  rows.push({ json: {
    callId: original.callId,
    endedReason: original.endedReason,
    transcript: String(original.transcript || '').slice(0, 500),
    callerName: extracted.callerName || null,
    callerPhone: extracted.callerPhone || original.callerPhoneFromPlatform || null,
    intent,
    sentiment,
    urgency,
    summary,
    actionRequested: extracted.actionRequested || null,
    followUpDate: extracted.followUpDate || null,
    urgent,
    urgentReason: reasons.join('; '),
    routingOutcome: urgent ? 'urgent' : 'routine',
    businessOwnerWhatsAppNumber: settings.businessOwnerWhatsAppNumber,
    sendWhatsAppAutomatically: settings.sendWhatsAppAutomatically === true,
    crmSystem: settings.crmSystem,
    checkedAt: new Date().toISOString()
  } });
}
return rows;

